args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?older ?olderLabel ?bOlder ?younger ?youngerLabel ?bYounger WHERE {
  VALUES (?p1 ?p2) { (dbr:Mario_Baccini dbr:Béchir_Sfar) }

  OPTIONAL { ?p1 dbo:birthDate ?dbo1. }
  OPTIONAL { ?p1 dbp:birthDate ?dbp1. }
  BIND(coalesce(?dbo1, ?dbp1) AS ?b1)

  OPTIONAL { ?p2 dbo:birthDate ?dbo2. }
  OPTIONAL { ?p2 dbp:birthDate ?dbp2. }
  BIND(coalesce(?dbo2, ?dbp2) AS ?b2)

  FILTER(bound(?b1) && bound(?b2))

  BIND(IF(?b1 < ?b2, ?p1, ?p2) AS ?older)
  BIND(IF(?b1 < ?b2, ?b1, ?b2) AS ?bOlder)
  BIND(IF(?b1 < ?b2, ?p2, ?p1) AS ?younger)
  BIND(IF(?b1 < ?b2, ?b2, ?b1) AS ?bYounger)

  OPTIONAL { ?older rdfs:label ?olderLabel . FILTER(lang(?olderLabel)='en') }
  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel)='en') }
}
LIMIT 1

